                  <!--                  图片-->
                </div>
                <div style="padding: 10px; font-size: 16px; font-weight: bold; color: #429900">3.教学环节</div>

                <div style="padding: 10px">
                  <div> &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;本课程通过<strong
                      style="color: #FF8D3E">视频授课</strong>
